argv:
set timeout 90
proc fail {code} {
  catch {send -- "\003"}
  after 300
  catch {close}
  catch {wait}
  exit $code
}
spawn env QWEN_TUI_RENDERER=opentui QWEN_CODE_SKIP_UPDATE_CHECK_ONCE=true bun packages/cli/dist/index.js
expect {
  -re {ready} {}
  -re {unexpected critical error|Error:} { fail 1 }
  timeout { fail 2 }
}
send -- "ZXQ"
expect {
  -re {ZXQ} {}
  timeout { fail 3 }
}
send -- "\177"
after 200
send -- "\r"
expect {
  -re {❯[^\r\n]*ZX} {}
  -re {unexpected critical error|Error:} { fail 4 }
  timeout { fail 5 }
}
send -- "\003"
expect {
  eof {}
  timeout { fail 6 }
}
